function About(){return <><SEO path="/about/"/><main><section className="category-hero about-hero"><div><span className="eyebrow">A LITTLE ABOUT US</span><h1>Good tailoring starts with <em>listening.</em></h1><p>Arisha Ladies Stitching &amp; Boutique is a female-owned tailoring business serving customers since 2021. Our one physical shop is at {BUSINESS.address}. We welcome stitching enquiries from across Lahore, with home delivery in confirmed service areas.</p><WhatsAppButton message="Assalam-o-Alaikum! I would like to know more about Arisha Ladies Stitching & Boutique."/></div><img src={IMAGES.stitching} alt="Tailoring and measuring inspiration"/></section><section className="section about-values"><div><span className="eyebrow">OUR APPROACH</span><h2>Personal details matter.</h2><p>We discuss the design, fabric, fit, finishing and expected timeline before confirming an order. Prices and availability should always be verified directly so there are no surprises.</p></div><div className="value-list"><p><CheckCircle2/> <span><strong>Clear communication</strong><br/>Agree on design details before stitching begins.</span></p><p><CheckCircle2/> <span><strong>Made around your idea</strong><br/>Bring a sketch, reference photo or your own fabric.</span></p><p><CheckCircle2/> <span><strong>Fit and finishing</strong><br/>Discuss trials, alterations and collection timing.</span></p></div></section><CTA/></main></>}

